// Quiz mode — Hard tier (100 questions).
// Same shape as easy.js — see that file's header comment.

export const questions = [
  { id: "q-hard-py-001", language: "python", question: "What is the output of: def f(a, b=[]): b.append(a); return b — then f(1); f(2)?", options: [{id:"a",text:"[1] then [2]"},{id:"b",text:"[1] then [1, 2]"},{id:"c",text:"[2] then [1]"},{id:"d",text:"Error on second call"}], correctOptionId: "b", explanation: "Mutable default arguments persist across calls since they're created once at function definition time, so the list accumulates: [1], then [1, 2]." },
  { id: "q-hard-py-002", language: "python", question: "What does the GIL (Global Interpreter Lock) primarily restrict in CPython?", options: [{id:"a",text:"Network access"},{id:"b",text:"Only one thread executes Python bytecode at a time, limiting true CPU-bound parallelism via threads"},{id:"c",text:"File I/O"},{id:"d",text:"Import statements"}], correctOptionId: "b", explanation: "The GIL prevents multiple native threads from executing Python bytecode simultaneously, which is why CPU-bound work often uses multiprocessing instead." },
  { id: "q-hard-py-003", language: "python", question: "What is the difference between __new__ and __init__?", options: [{id:"a",text:"They are identical"},{id:"b",text:"__new__ creates and returns the instance; __init__ initializes an already-created instance"},{id:"c",text:"__init__ is called before __new__"},{id:"d",text:"__new__ only exists for exceptions"}], correctOptionId: "b", explanation: "__new__ is the actual object constructor (returns the instance); __init__ then sets it up, receiving the instance as self." },
  { id: "q-hard-py-004", language: "python", question: "Why might 'a is b' be True for small integers but False for large ones, even if a == b?", options: [{id:"a",text:"CPython caches/interns small integers (-5 to 256) as singletons"},{id:"b",text:"It's a bug"},{id:"c",text:"Large integers use different memory allocators always"},{id:"d",text:"Integer comparison is undefined behavior in Python"}], correctOptionId: "a", explanation: "CPython pre-allocates and reuses small integer objects, so identical small ints share the same object; larger ones typically don't." },
  { id: "q-hard-py-005", language: "python", question: "What does metaclass=ABCMeta actually change about a class at a low level?", options: [{id:"a",text:"Nothing, it's purely cosmetic"},{id:"b",text:"It controls how the class itself is constructed, enabling enforcement of abstract methods at instantiation time"},{id:"c",text:"It changes the class's string representation only"},{id:"d",text:"It disables inheritance"}], correctOptionId: "b", explanation: "A metaclass controls class creation; ABCMeta uses this to raise TypeError if you try to instantiate a class with unimplemented abstract methods." },
  { id: "q-hard-py-006", language: "python", question: "What is a key difference between multiprocessing and threading for CPU-bound work in Python?", options: [{id:"a",text:"No difference due to the GIL"},{id:"b",text:"multiprocessing uses separate processes (separate GILs), enabling true parallel CPU execution"},{id:"c",text:"threading is always faster for CPU-bound tasks"},{id:"d",text:"multiprocessing can't share any data"}], correctOptionId: "b", explanation: "Each process has its own Python interpreter and GIL, so multiprocessing achieves real parallelism for CPU-bound work that threading cannot due to the GIL." },
  { id: "q-hard-py-007", language: "python", question: "What does '__slots__' NOT prevent?", options: [{id:"a",text:"Subclasses adding their own __dict__ unless they also define __slots__"},{id:"b",text:"Setting attributes listed in __slots__"},{id:"c",text:"Reduced memory usage"},{id:"d",text:"Faster attribute access in some cases"}], correctOptionId: "a", explanation: "If a subclass doesn't define its own __slots__, it gets a __dict__ back, allowing arbitrary attributes and partially defeating the memory benefit." },
  { id: "q-hard-py-008", language: "python", question: "What is the output of: print(0.1 + 0.2 == 0.3)?", options: [{id:"a",text:"True"},{id:"b",text:"False"},{id:"c",text:"Error"},{id:"d",text:"None"}], correctOptionId: "b", explanation: "Floating-point representation error means 0.1 + 0.2 is actually 0.30000000000000004, not exactly 0.3." },
  { id: "q-hard-py-009", language: "python", question: "What does asyncio.create_task() do differently from just calling 'await coroutine()'?", options: [{id:"a",text:"create_task schedules the coroutine to run concurrently in the background immediately, not waiting for it"},{id:"b",text:"They are identical"},{id:"c",text:"create_task blocks until completion"},{id:"d",text:"await runs the coroutine in a new thread"}], correctOptionId: "a", explanation: "create_task wraps a coroutine in a Task, scheduling it to run concurrently, while a bare await pauses execution until that coroutine finishes." },
  { id: "q-hard-py-010", language: "python", question: "What happens if you mutate a list while iterating over it directly with a for loop?", options: [{id:"a",text:"Python automatically handles it safely"},{id:"b",text:"Items can be skipped or the loop can behave unexpectedly, since the iterator tracks a moving index"},{id:"c",text:"It always raises an exception"},{id:"d",text:"It creates a copy automatically"}], correctOptionId: "b", explanation: "Removing/adding items shifts subsequent indices, so the loop can skip elements silently — iterate over a copy (list[:]) to mutate safely." },
  { id: "q-hard-py-011", language: "python", question: "What is the purpose of __hash__ and why must it be consistent with __eq__?", options: [{id:"a",text:"Objects considered equal (via __eq__) must have the same hash, or they'll break in sets/dicts"},{id:"b",text:"__hash__ has no relationship to __eq__"},{id:"c",text:"__hash__ is only used for printing"},{id:"d",text:"__hash__ must always return a unique value per object"}], correctOptionId: "a", explanation: "Hash-based collections rely on: if a == b, then hash(a) == hash(b); violating this causes lookup bugs in sets/dicts." },
  { id: "q-hard-py-012", language: "python", question: "What does 'sys.setrecursionlimit()' actually control?", options: [{id:"a",text:"The maximum Python call stack depth before RecursionError"},{id:"b",text:"Loop iteration count"},{id:"c",text:"Memory allocation limit"},{id:"d",text:"Thread count"}], correctOptionId: "a", explanation: "It sets the maximum depth of the Python interpreter's call stack, guarding against stack overflows from deep/infinite recursion." },
  { id: "q-hard-py-013", language: "python", question: "Why can a bound method and its underlying function have different identity (is comparison)?", options: [{id:"a",text:"Bound methods are created fresh each time you access instance.method, wrapping the function with the instance"},{id:"b",text:"It's always the same object"},{id:"c",text:"Methods are cached permanently"},{id:"d",text:"This never happens in Python"}], correctOptionId: "a", explanation: "Accessing instance.method via the descriptor protocol creates a new bound method object each time, so 'instance.method is instance.method' is often False." },
  { id: "q-hard-py-014", language: "python", question: "What is the effect of using a weakref.ref instead of a normal reference?", options: [{id:"a",text:"It doesn't prevent the referenced object from being garbage collected"},{id:"b",text:"It's identical to a normal reference"},{id:"c",text:"It prevents garbage collection more aggressively"},{id:"d",text:"It only works with strings"}], correctOptionId: "a", explanation: "Weak references let you refer to an object without increasing its reference count, useful for caches that shouldn't keep objects alive." },
  { id: "q-hard-py-015", language: "python", question: "What does the descriptor protocol (__get__, __set__, __delete__) enable?", options: [{id:"a",text:"Custom logic for attribute access, the mechanism behind @property"},{id:"b",text:"Only used for imports"},{id:"c",text:"String formatting"},{id:"d",text:"Exception handling"}], correctOptionId: "a", explanation: "Descriptors let a class customize what happens when its attributes are get/set/deleted; @property is implemented using descriptors." },
  { id: "q-hard-py-016", language: "python", question: "In async code, what's a risk of calling a blocking (synchronous) function inside an async def without offloading it?", options: [{id:"a",text:"None, async functions handle this automatically"},{id:"b",text:"It blocks the entire event loop, stalling all other concurrent tasks"},{id:"c",text:"It runs on a separate thread automatically"},{id:"d",text:"It raises a SyntaxError"}], correctOptionId: "b", explanation: "A blocking call inside an async function freezes the single-threaded event loop, preventing any other coroutine from making progress until it returns." },
  { id: "q-hard-py-017", language: "python", question: "What does 'super()' resolve to in a class with multiple inheritance?", options: [{id:"a",text:"Always the immediate parent class named in the class definition"},{id:"b",text:"The next class in the MRO (Method Resolution Order), which may not be the 'obvious' parent"},{id:"c",text:"A random base class"},{id:"d",text:"It always fails with multiple inheritance"}], correctOptionId: "b", explanation: "super() follows the C3 linearization MRO, so in diamond inheritance it may skip to a class that isn't the direct parent written in the class statement." },
  { id: "q-hard-py-018", language: "python", question: "What is a subtle issue with catching a bare 'except:' clause?", options: [{id:"a",text:"It also catches SystemExit and KeyboardInterrupt, which usually shouldn't be silently swallowed"},{id:"b",text:"It only catches ValueError"},{id:"c",text:"It's identical to 'except Exception:'"},{id:"d",text:"It's the recommended best practice"}], correctOptionId: "a", explanation: "A bare except catches BaseException, including SystemExit/KeyboardInterrupt, which can make Ctrl+C or sys.exit() silently fail to work as expected." },
  { id: "q-hard-py-019", language: "python", question: "What does 'from __future__ import annotations' change?", options: [{id:"a",text:"Nothing meaningful"},{id:"b",text:"Type annotations are treated as strings at runtime (postponed evaluation), avoiding forward-reference issues"},{id:"c",text:"It enables Python 4 features"},{id:"d",text:"It disables type hints entirely"}], correctOptionId: "b", explanation: "This makes annotations lazily evaluated strings, letting you reference not-yet-defined classes and slightly improving import performance." },
  { id: "q-hard-py-020", language: "python", question: "Why might using a list as a dictionary key fail?", options: [{id:"a",text:"Lists are unhashable (mutable), so they can't be used as dict keys"},{id:"b",text:"Lists are too large"},{id:"c",text:"It works fine in all cases"},{id:"d",text:"Only tuples of length > 3 fail"}], correctOptionId: "a", explanation: "Dict keys must be hashable, and lists are mutable and therefore unhashable — using one as a key raises TypeError." },
  { id: "q-hard-py-021", language: "python", question: "What is the purpose of Python's 'contextvars' module?", options: [{id:"a",text:"Managing context-local state that works correctly across async tasks, unlike thread-locals"},{id:"b",text:"Only for CLI argument parsing"},{id:"c",text:"Managing environment variables"},{id:"d",text:"A replacement for global variables with no special behavior"}], correctOptionId: "a", explanation: "ContextVar provides state that's properly isolated per async task/coroutine, addressing a gap where threading.local() doesn't work well with asyncio." },
  { id: "q-hard-py-022", language: "python", question: "What does 'functools.wraps' do when writing a decorator?", options: [{id:"a",text:"Preserves the wrapped function's metadata (name, docstring) on the wrapper"},{id:"b",text:"Makes the decorator run faster"},{id:"c",text:"Converts the function to async"},{id:"d",text:"Adds caching automatically"}], correctOptionId: "a", explanation: "Without @wraps, a decorated function's __name__ and __doc__ get replaced by the wrapper's, which functools.wraps fixes by copying them over." },
  { id: "q-hard-py-023", language: "python", question: "What is a potential issue with using asyncio.sleep(0) versus not yielding at all in a tight loop within a coroutine?", options: [{id:"a",text:"asyncio.sleep(0) yields control back to the event loop, letting other tasks run; omitting it can starve other coroutines"},{id:"b",text:"They are functionally identical"},{id:"c",text:"asyncio.sleep(0) always takes at least 1 second"},{id:"d",text:"It has no effect on scheduling"}], correctOptionId: "a", explanation: "sleep(0) is a common idiom to explicitly yield control in a cooperative event loop, preventing one coroutine from monopolizing execution." },
  { id: "q-hard-py-024", language: "python", question: "What does '__init_subclass__' allow a base class to do?", options: [{id:"a",text:"Hook into and customize the creation of its subclasses without needing a metaclass"},{id:"b",text:"Prevent all subclassing"},{id:"c",text:"Only works on abstract classes"},{id:"d",text:"Modify the base class itself after subclasses are created"}], correctOptionId: "a", explanation: "__init_subclass__ is a simpler alternative to metaclasses for validating or registering subclasses as they're defined." },
  { id: "q-hard-py-025", language: "python", question: "Why does 'except Exception as e: raise e' lose the original traceback context compared to a bare 'raise'?", options: [{id:"a",text:"It doesn't — both preserve the traceback identically in modern Python"},{id:"b",text:"'raise e' technically re-raises but can reset __traceback__ framing in some contexts; bare 'raise' unambiguously preserves the original traceback"},{id:"c",text:"'raise e' always crashes the interpreter"},{id:"d",text:"Bare raise only works outside except blocks"}], correctOptionId: "b", explanation: "A bare 'raise' inside an except block is the idiomatic way to re-raise the current exception with its original traceback fully intact." },
  { id: "q-hard-fl-001", language: "flutter", question: "Why can excessive use of Provider.of(context) (listen: true) throughout a widget tree hurt performance?", options: [{id:"a",text:"It has no performance impact"},{id:"b",text:"Every listening widget rebuilds on any change to the provided value, even parts of it the widget doesn't use"},{id:"c",text:"It only affects debug builds"},{id:"d",text:"It disables hot reload"}], correctOptionId: "b", explanation: "Broad listening causes unnecessary rebuilds; using Selector or narrowing what's listened to avoids rebuilding widgets that don't depend on the changed data." },
  { id: "q-hard-fl-002", language: "flutter", question: "What is the difference between 'Element', 'Widget', and 'RenderObject' in Flutter's architecture?", options: [{id:"a",text:"They're interchangeable terms for the same thing"},{id:"b",text:"Widget is an immutable config; Element is the mutable instance in the tree managing lifecycle; RenderObject handles layout/painting"},{id:"c",text:"RenderObject is only used for text"},{id:"d",text:"Element is deprecated in favor of Widget"}], correctOptionId: "b", explanation: "Flutter's three trees: Widgets (configuration), Elements (persistent instances managing widget lifecycle), and RenderObjects (actual layout/paint logic)." },
  { id: "q-hard-fl-003", language: "flutter", question: "Why does calling setState() inside build() cause problems?", options: [{id:"a",text:"It can trigger an infinite rebuild loop since build() itself schedules another build"},{id:"b",text:"It's the recommended pattern"},{id:"c",text:"It only affects the AppBar"},{id:"d",text:"Nothing happens, it's a no-op"}], correctOptionId: "a", explanation: "Calling setState() during build() re-triggers a build synchronously, which Flutter detects and throws an error for to prevent an infinite loop." },
  { id: "q-hard-fl-004", language: "flutter", question: "What does the 'key' parameter solve when reordering a list of StatefulWidgets?", options: [{id:"a",text:"Nothing meaningful"},{id:"b",text:"Without keys, Flutter may match State objects to widgets by position, causing state to 'jump' between items when the list is reordered"},{id:"c",text:"Keys only affect widget color"},{id:"d",text:"Keys are required for all widgets, stateless or not"}], correctOptionId: "b", explanation: "Keys let Flutter correctly track which State belongs to which logical item even as the list order changes, avoiding state mismatches." },
  { id: "q-hard-fl-005", language: "flutter", question: "Why might a widget rebuild even though its build() output is functionally identical to before?", options: [{id:"a",text:"Flutter always skips identical output automatically"},{id:"b",text:"Flutter rebuilds are triggered by widget/state changes, not output diffing — it always calls build() again unless the widget is const/unchanged"},{id:"c",text:"This never happens"},{id:"d",text:"Only StatelessWidgets can rebuild"}], correctOptionId: "b", explanation: "Rebuild triggers (setState, InheritedWidget changes, parent rebuilds) cause build() to run again regardless of whether the output would differ, unless const optimizations apply." },
  { id: "q-hard-fl-006", language: "flutter", question: "What is a risk of storing a BuildContext and using it after an async gap (e.g. after an awaited Future)?", options: [{id:"a",text:"No risk at all"},{id:"b",text:"The widget may have been disposed/unmounted by the time the async operation completes, making the context invalid"},{id:"c",text:"BuildContext is immutable and always safe"},{id:"d",text:"It only matters for StatelessWidget"}], correctOptionId: "b", explanation: "If the widget is removed from the tree while awaiting, using its stale context (e.g. for Navigator or ScaffoldMessenger) can throw or behave incorrectly — checking mounted first is the safeguard." },
  { id: "q-hard-fl-007", language: "flutter", question: "What is the purpose of 'IndexedStack' compared to 'Stack'?", options: [{id:"a",text:"IndexedStack shows only one child at a time (by index) while keeping all children's state alive"},{id:"b",text:"They're identical"},{id:"c",text:"IndexedStack disposes hidden children"},{id:"d",text:"IndexedStack only works with two children"}], correctOptionId: "a", explanation: "IndexedStack lays out and keeps all children alive but paints only the one at the given index — useful for tab views that preserve state when switching." },
  { id: "q-hard-fl-008", language: "flutter", question: "Why is it generally discouraged to do heavy computation directly inside a build() method?", options: [{id:"a",text:"build() is not allowed to contain any logic"},{id:"b",text:"build() can be called frequently (every frame/rebuild), so expensive work there repeats unnecessarily and can cause jank"},{id:"c",text:"It has no real downside"},{id:"d",text:"build() runs on a background isolate automatically"}], correctOptionId: "b", explanation: "Since build() may run many times, expensive synchronous work there directly impacts frame rendering time — better to compute once and cache, or memoize." },
  { id: "q-hard-fl-009", language: "flutter", question: "What does 'compute()' (from Flutter's foundation library) do?", options: [{id:"a",text:"Runs a function on a separate isolate, useful for CPU-heavy work without blocking the UI"},{id:"b",text:"Performs arithmetic only"},{id:"c",text:"Computes layout constraints"},{id:"d",text:"Runs synchronously on the main isolate"}], correctOptionId: "a", explanation: "compute() spawns a new isolate to run a top-level function, avoiding UI jank from CPU-intensive work like JSON parsing of large payloads." },
  { id: "q-hard-fl-010", language: "flutter", question: "Why can't isolates in Dart directly share mutable objects with each other?", options: [{id:"a",text:"They can, freely"},{id:"b",text:"Each isolate has its own memory heap; data must be copied/serialized when passed via message passing"},{id:"c",text:"Isolates share the same heap by default"},{id:"d",text:"This restriction only applies to Flutter, not Dart"}], correctOptionId: "b", explanation: "Isolates are memory-isolated by design (hence the name), communicating only via message passing, which copies data rather than sharing references." },
  { id: "q-hard-fl-011", language: "flutter", question: "What is a common cause of a 'setState() called after dispose()' error?", options: [{id:"a",text:"An async callback (e.g. a Future or Timer) completing after the widget was removed from the tree, then calling setState()", },{id:"b",text:"Calling setState() inside initState()"},{id:"c",text:"It happens randomly with no cause"},{id:"d",text:"Using const constructors"}], correctOptionId: "a", explanation: "If a pending async operation resolves after the widget is disposed, calling setState() on the now-gone State throws this error — checking mounted before calling it prevents it." },
  { id: "q-hard-fl-012", language: "flutter", question: "What does the 'Ticker' concept in Flutter's animation system represent?", options: [{id:"a",text:"A callback invoked on every frame, driving animation progression"},{id:"b",text:"A network polling mechanism"},{id:"c",text:"A widget for showing a clock"},{id:"d",text:"A logging utility"}], correctOptionId: "a", explanation: "Tickers fire a callback each frame (synced to the display refresh), which AnimationController uses to advance animation values over time." },
  { id: "q-hard-fastapi-001", language: "fastapi", question: "Why might mixing sync (def) and async (async def) database calls in the same FastAPI app cause performance issues?", options: [{id:"a",text:"Sync path operations run in a threadpool, while async ones run on the event loop; a sync call in an async function still blocks the loop"},{id:"b",text:"There's no difference in how they're executed"},{id:"c",text:"Sync functions are always faster"},{id:"d",text:"FastAPI forbids mixing them"}], correctOptionId: "a", explanation: "FastAPI runs regular 'def' routes in a threadpool automatically, but a blocking call made inside an 'async def' route runs directly on the event loop and blocks it." },
  { id: "q-hard-fastapi-002", language: "fastapi", question: "What is a subtle issue with using a mutable default (e.g. a dict) as a Pydantic model field's default value?", options: [{id:"a",text:"Pydantic handles this safely by creating a new instance per model instance via default_factory, unlike Python's own mutable-default pitfall"},{id:"b",text:"It behaves identically to Python's classic mutable default argument bug"},{id:"c",text:"Pydantic forbids dict fields entirely"},{id:"d",text:"It always raises a ValidationError"}], correctOptionId: "a", explanation: "Pydantic is aware of the mutable-default problem and (with default_factory, or automatically in modern versions) avoids sharing the same mutable object across instances." },
  { id: "q-hard-fastapi-003", language: "fastapi", question: "What is a risk of using a global mutable variable to cache state in a FastAPI app running with multiple worker processes?", options: [{id:"a",text:"No risk, all workers share memory"},{id:"b",text:"Each worker process has its own memory, so the cache is inconsistent across workers"},{id:"c",text:"FastAPI automatically synchronizes globals across processes"},{id:"d",text:"This only matters for GET requests"}], correctOptionId: "b", explanation: "Running with multiple processes (e.g. via gunicorn workers) means each has an independent memory space — an in-process cache won't be shared, requiring something like Redis instead." },
  { id: "q-hard-fastapi-004", language: "fastapi", question: "Why does declaring a dependency with 'yield' let you run cleanup code, and what happens if an exception occurs in the route?", options: [{id:"a",text:"The code after yield still runs (in a finally-like manner), letting you clean up even if the route raised an exception"},{id:"b",text:"The cleanup code is skipped entirely if an exception occurs"},{id:"c",text:"yield dependencies can't have cleanup logic"},{id:"d",text:"The exception is silently swallowed by the dependency"}], correctOptionId: "a", explanation: "FastAPI treats yield-based dependencies similarly to a context manager — code after yield acts as teardown and still executes on exceptions, letting you close resources reliably." },
  { id: "q-hard-fastapi-005", language: "fastapi", question: "What is a potential N+1 query problem when serializing related ORM objects through a Pydantic response_model?", options: [{id:"a",text:"Accessing a lazy-loaded relationship for each item in a list triggers a separate DB query per item unless eagerly loaded"},{id:"b",text:"FastAPI automatically batches all queries"},{id:"c",text:"This can't happen with Pydantic"},{id:"d",text:"Only synchronous ORMs have this issue"}], correctOptionId: "a", explanation: "If a relationship isn't eagerly loaded (e.g. via joinedload), accessing it during serialization for each row in a list causes one query per row — a classic N+1 problem." },
  { id: "q-hard-fastapi-006", language: "fastapi", question: "Why can validating a very large request body with Pydantic become a performance bottleneck, and what's a common mitigation?", options: [{id:"a",text:"Validation is always instant regardless of size"},{id:"b",text:"Deep validation of large/nested payloads has real CPU cost; streaming or partial validation can mitigate it for very large inputs"},{id:"c",text:"FastAPI skips validation for large bodies automatically"},{id:"d",text:"This only affects GET requests"}], correctOptionId: "b", explanation: "Pydantic validation walks the full structure of the input, which has real cost for very large or deeply nested payloads — for extreme cases, streaming parsing avoids loading everything into memory/validating it all at once." },
  { id: "q-hard-fastapi-007", language: "fastapi", question: "What is the effect of dependency caching in FastAPI when the same dependency is used by multiple parameters/sub-dependencies within a single request?", options: [{id:"a",text:"By default, FastAPI calls the dependency function only once per request and reuses the result (unless use_cache=False)"},{id:"b",text:"It's called once per usage, always"},{id:"c",text:"Dependencies are never cached"},{id:"d",text:"Caching only applies to yield dependencies"}], correctOptionId: "a", explanation: "FastAPI caches a dependency's result within a single request by default, so multiple routes/dependencies referencing the same dependency get the same computed value without redundant calls." },
  { id: "q-hard-fastapi-008", language: "fastapi", question: "Why might returning a raw SQLAlchemy ORM object directly (without a response_model) leak unintended data or cause serialization errors?", options: [{id:"a",text:"ORM objects can include internal/relationship attributes not meant for the API, and FastAPI may not know how to serialize all of them"},{id:"b",text:"This is always perfectly safe with no consideration needed"},{id:"c",text:"FastAPI automatically strips sensitive fields"},{id:"d",text:"ORM objects can't be returned at all"}], correctOptionId: "a", explanation: "Without an explicit response_model, you risk exposing internal fields or hitting serialization issues with lazy-loaded relationships — an explicit schema controls exactly what's exposed." },
  { id: "q-hard-fastapi-009", language: "fastapi", question: "What is a subtlety of exception handling order when you have both a specific exception handler and a more general one (e.g. for Exception) registered via @app.exception_handler?", options: [{id:"a",text:"The most specific matching exception type's handler takes precedence, similar to except clause ordering"},{id:"b",text:"The general handler always runs first regardless of type"},{id:"c",text:"Only one exception handler can ever be registered"},{id:"d",text:"Handler order is random"}], correctOptionId: "a", explanation: "FastAPI/Starlette dispatch to the handler registered for the most specific matching exception type, similar to how Python resolves except clauses by specificity." },
  { id: "q-hard-fastapi-010", language: "fastapi", question: "Why is it recommended to avoid doing heavy blocking work inside a FastAPI BackgroundTasks function if the app is otherwise fully async?", options: [{id:"a",text:"BackgroundTasks run in the same event loop after the response is sent, so blocking code there still blocks the loop for other requests"},{id:"b",text:"BackgroundTasks always run in a separate isolated process"},{id:"c",text:"This has no impact on other requests"},{id:"d",text:"BackgroundTasks can only run synchronous code, which is fine"}], correctOptionId: "a", explanation: "BackgroundTasks execute after the response, but still on the same event loop, so a blocking call there can stall the server just like within a route handler." },
  { id: "q-hard-py-026", language: "python", question: "What is the output of: a = (1,); print(type(a))?", options: [{id:"a",text:"<class 'int'>"},{id:"b",text:"<class 'tuple'>"},{id:"c",text:"Error, invalid syntax"},{id:"d",text:"<class 'list'>"}], correctOptionId: "b", explanation: "A trailing comma is what makes a tuple, not the parentheses — (1,) is a one-element tuple; (1) alone would just be the int 1." },
  { id: "q-hard-py-027", language: "python", question: "Why does 'True + True' evaluate to 2 in Python?", options: [{id:"a",text:"It raises a TypeError"},{id:"b",text:"bool is a subclass of int, so True behaves as 1 and False as 0 in arithmetic"},{id:"c",text:"Python auto-converts to strings first"},{id:"d",text:"It actually evaluates to False"}], correctOptionId: "b", explanation: "Since bool subclasses int with True=1 and False=0, arithmetic operators work on booleans as if they were their underlying integer values." },
  { id: "q-hard-py-028", language: "python", question: "What is a 'closure' in Python, and what common pitfall occurs when creating closures inside a loop?", options: [{id:"a",text:"A function capturing variables from an enclosing scope; loop closures often capture the loop variable by reference, so all closures see its final value"},{id:"b",text:"A closure copies the variable's value at creation time automatically"},{id:"c",text:"Closures are unrelated to loops"},{id:"d",text:"Python doesn't support closures"}], correctOptionId: "a", explanation: "Since closures capture variables (not values), a list of lambdas created in a loop referencing the loop variable will all see its final value unless you bind it explicitly (e.g. via a default argument)." },
  { id: "q-hard-py-029", language: "python", question: "What does '__eq__' returning NotImplemented (rather than False) enable?", options: [{id:"a",text:"Lets Python fall back to trying the other object's __eq__ (or reflected comparison) instead of assuming inequality"},{id:"b",text:"Nothing different from returning False"},{id:"c",text:"It always raises an error"},{id:"d",text:"It disables comparison entirely"}], correctOptionId: "a", explanation: "Returning NotImplemented signals 'I don't know how to compare with this type,' letting Python try the reflected method on the other operand before giving up." },
  { id: "q-hard-py-030", language: "python", question: "Why is 'sum(list_of_strings, \"\")' generally discouraged compared to ''.join(list_of_strings)?", options: [{id:"a",text:"sum() with strings creates a new string at every step, making it O(n\u00b2) in the worst case; join() is O(n)"},{id:"b",text:"sum() doesn't work with strings at all"},{id:"c",text:"They have identical performance"},{id:"d",text:"join() only works with tuples"}], correctOptionId: "a", explanation: "Repeated string concatenation via sum() creates a new string object each time, giving quadratic time complexity, while str.join() is optimized for linear-time concatenation." },
  { id: "q-hard-py-031", language: "python", question: "What is the difference between copy.copy() on a class instance and Python's default attribute lookup via __getattr__ fallback?", options: [{id:"a",text:"copy.copy() typically uses __reduce_ex__/__copy__ if defined, bypassing normal attribute access entirely"},{id:"b",text:"They always behave the same"},{id:"c",text:"copy.copy() calls __init__ again"},{id:"d",text:"__getattr__ is invoked during every copy operation"}], correctOptionId: "a", explanation: "copy.copy() uses the copy protocol (__copy__, __reduce_ex__, etc.), not the normal attribute-access path, so custom __getattr__ logic isn't necessarily involved." },
  { id: "q-hard-py-032", language: "python", question: "Why does modifying a class attribute via an instance (e.g. instance.class_attr = 5) not affect the class attribute itself?", options: [{id:"a",text:"It creates a new instance attribute that shadows the class attribute, rather than modifying the class attribute in place"},{id:"b",text:"It always raises an AttributeError"},{id:"c",text:"It modifies the class attribute for all instances"},{id:"d",text:"Class attributes can't be shadowed"}], correctOptionId: "a", explanation: "Assignment on an instance creates/overwrites an instance-level attribute in that instance's __dict__, leaving the class attribute (and other instances) untouched." },
  { id: "q-hard-py-033", language: "python", question: "What is a key reason 'async def' functions can't simply be called like normal functions to get their result?", options: [{id:"a",text:"Calling an async function returns a coroutine object, which must be awaited or scheduled to actually run"},{id:"b",text:"Async functions run immediately just like normal functions"},{id:"c",text:"Async functions have no return value"},{id:"d",text:"This is a limitation only in Python 2"}], correctOptionId: "a", explanation: "Calling an async function doesn't execute its body; it creates a coroutine object that needs to be awaited (or run via the event loop) to actually execute." },
  { id: "q-hard-py-034", language: "python", question: "Why can 'id()' values be reused for different objects during a program's execution?", options: [{id:"a",text:"id() reflects memory address in CPython; once an object is garbage collected, that memory can be reused by a new object"},{id:"b",text:"id() values are randomly generated and unrelated to memory"},{id:"c",text:"This never happens in practice"},{id:"d",text:"id() always increments and never repeats"}], correctOptionId: "a", explanation: "Since id() often corresponds to memory address in CPython, and memory is reclaimed after garbage collection, a later object can end up with the same id() as an earlier, now-deleted one." },
  { id: "q-hard-py-035", language: "python", question: "What subtlety exists in using 'try/except/else' versus just putting code after try without else?", options: [{id:"a",text:"'else' only runs if no exception occurred in the try block, distinguishing it from code that would run regardless"},{id:"b",text:"'else' always runs regardless of exceptions"},{id:"c",text:"'else' is a syntax error in try blocks"},{id:"d",text:"'else' replaces the need for except"}], correctOptionId: "a", explanation: "The else clause runs only if the try block completed without raising, which is useful to separate 'code that might raise' from 'code that should only run on success'." },
  { id: "q-hard-fl-013", language: "flutter", question: "What is the purpose of 'LayoutBuilder' and why can't you get a widget's rendered size directly during build()?", options: [{id:"a",text:"LayoutBuilder provides constraints during layout since actual sizes aren't known until the layout phase, after build()"},{id:"b",text:"LayoutBuilder is only for styling"},{id:"c",text:"Widget sizes are always known immediately during build()"},{id:"d",text:"LayoutBuilder replaces MediaQuery entirely"}], correctOptionId: "a", explanation: "Flutter's pipeline separates build (config), layout (sizing), and paint; LayoutBuilder gives you the incoming constraints during the layout phase, which isn't available at build time." },
  { id: "q-hard-fl-014", language: "flutter", question: "Why does using an AnimatedBuilder combined with a static child parameter improve animation performance over rebuilding the whole subtree?", options: [{id:"a",text:"The static 'child' is built once and reused across animation frames, avoiding rebuilding expensive parts that don't change"},{id:"b",text:"AnimatedBuilder has no performance benefit"},{id:"c",text:"child is rebuilt every frame regardless"},{id:"d",text:"AnimatedBuilder disables animations for children"}], correctOptionId: "a", explanation: "AnimatedBuilder's 'child' parameter is built once and passed into the builder function on every frame, letting expensive static parts of the tree be skipped during animation." },
  { id: "q-hard-fl-015", language: "flutter", question: "What is a common cause of 'setState() or markNeedsBuild() called during build' errors?", options: [{id:"a",text:"Triggering a state change synchronously as a side effect of the build() method itself, e.g. inside a widget's build call chain"},{id:"b",text:"This error is unrelated to setState timing"},{id:"c",text:"It only happens with StatelessWidget"},{id:"d",text:"It happens when using const constructors"}], correctOptionId: "a", explanation: "Flutter forbids scheduling a new build while already building, since it can lead to infinite loops or inconsistent frames — such calls should be deferred (e.g. via addPostFrameCallback)." },
  { id: "q-hard-fl-016", language: "flutter", question: "Why might two functionally-identical widgets built by different parent widgets NOT be treated as 'the same' during reconciliation, causing unnecessary State disposal/recreation?", options: [{id:"a",text:"Flutter's default reconciliation matches by widget type AND position in the tree (and key if provided) — without keys, a changed type at the same position causes recreation"},{id:"b",text:"Flutter always treats identical widgets as the same regardless of position"},{id:"c",text:"Reconciliation ignores widget type entirely"},{id:"d",text:"This only applies to StatelessWidget"}], correctOptionId: "a", explanation: "Element reconciliation compares runtimeType and key at each tree position; if the type changes at a given slot, the old Element (and its State) is discarded and a new one created, even if the new widget is 'conceptually similar'." },
  { id: "q-hard-fl-017", language: "flutter", question: "What is a potential downside of overusing GlobalKey throughout an app?", options: [{id:"a",text:"GlobalKeys are relatively expensive (O(1) lookup but with overhead) and force a unique Element for that key across the whole app, limiting Flutter's ability to reuse/optimize"},{id:"b",text:"GlobalKeys have zero cost and should always be preferred over local keys"},{id:"c",text:"GlobalKeys can only be used once per app lifetime, ever"},{id:"d",text:"GlobalKeys disable hot reload"}], correctOptionId: "a", explanation: "GlobalKeys carry more overhead than local keys and constrain the framework's tree optimizations since a GlobalKey'd widget's Element can be relocated but not duplicated." },
  { id: "q-hard-fl-018", language: "flutter", question: "Why does calling 'await' inside a widget's build() method not work as one might expect?", options: [{id:"a",text:"build() must be synchronous and return a Widget immediately; you can't make it async, so async work needs FutureBuilder/state instead"},{id:"b",text:"build() can be freely marked async in Flutter"},{id:"c",text:"await inside build() pauses the whole app correctly"},{id:"d",text:"This works fine and is the recommended pattern"}], correctOptionId: "a", explanation: "build() has a fixed synchronous signature returning Widget; it cannot be async, so asynchronous data must be handled via FutureBuilder, StreamBuilder, or state populated elsewhere (e.g. initState)." },
  { id: "q-hard-fl-019", language: "flutter", question: "What is the significance of 'didUpdateWidget(oldWidget)' in a State class?", options: [{id:"a",text:"Called when the parent rebuilds this widget with new configuration but reuses the same State object, letting you react to changed widget properties"},{id:"b",text:"Called only once, at creation"},{id:"c",text:"Called when the widget is permanently removed"},{id:"d",text:"Identical to initState"}], correctOptionId: "a", explanation: "didUpdateWidget fires when the widget is rebuilt with a new configuration but the State persists, allowing comparison against oldWidget to react to prop changes (e.g. restarting an animation)." },
  { id: "q-hard-fl-020", language: "flutter", question: "Why can a Stack with Positioned children behave unexpectedly if the Stack itself has unbounded constraints (e.g. inside a Column without a fixed size)?", options: [{id:"a",text:"Stack without bounded constraints sizes itself to its non-positioned children (or throws if none), so Positioned children may not have a clear area to position within"},{id:"b",text:"Stack always ignores its constraints entirely"},{id:"c",text:"Positioned widgets require no size information ever"},{id:"d",text:"This scenario is always an error"}], correctOptionId: "a", explanation: "Stack's default sizing behavior depends on its non-positioned children (or expands to fill if constraints are bounded); in an unbounded context, results can be surprising or trigger layout exceptions without an explicit size (e.g. via SizedBox)." },
  { id: "q-hard-fl-021", language: "flutter", question: "What is a subtlety of using 'Future.microtask' or scheduling work via addPostFrameCallback right after calling setState()?", options: [{id:"a",text:"addPostFrameCallback runs after the current frame completes rendering, useful for work that must happen after layout/paint (e.g. scrolling to a newly built widget)"},{id:"b",text:"They are functionally identical to calling code synchronously in build()"},{id:"c",text:"addPostFrameCallback runs before build()"},{id:"d",text:"This pattern is never necessary in Flutter"}], correctOptionId: "a", explanation: "addPostFrameCallback defers a callback until after the current frame is rendered, which is necessary when you need up-to-date layout information (like a RenderBox's size) that isn't available during build." },
  { id: "q-hard-fl-022", language: "flutter", question: "Why might two widgets that look visually identical still cause different performance characteristics if one uses 'Opacity' and the other uses a pre-baked semi-transparent color/asset?", options: [{id:"a",text:"The Opacity widget composites its child into an offscreen buffer, which is more expensive than a color/asset that's already transparent when painted directly"},{id:"b",text:"Opacity has no performance cost, ever"},{id:"c",text:"Both approaches are always identical in cost"},{id:"d",text:"Only AnimatedOpacity has a performance cost"}], correctOptionId: "a", explanation: "Opacity forces an extra compositing pass (rendering to an offscreen layer before blending), whereas baking transparency into a color or image avoids that extra step." },
  { id: "q-hard-fastapi-011", language: "fastapi", question: "What is a subtlety of returning a Pydantic model with computed/derived fields versus fields taken directly from the ORM object?", options: [{id:"a",text:"Computed fields need either a Pydantic computed_field/property or explicit construction in the route, since the ORM object itself won't have them"},{id:"b",text:"FastAPI computes all derived fields automatically from field names alone"},{id:"c",text:"Computed fields aren't supported by Pydantic at all"},{id:"d",text:"ORM objects automatically include any field the response_model declares"}], correctOptionId: "a", explanation: "A field that doesn't exist on the underlying ORM object needs explicit logic — either a Pydantic computed_field, a validator, or building the response model manually in the route." },
  { id: "q-hard-fastapi-012", language: "fastapi", question: "Why can chaining multiple Depends() that each open their own DB session lead to subtle bugs in a single request?", options: [{id:"a",text:"Separate sessions may not see each other's uncommitted changes, causing inconsistent reads within what should be one logical transaction"},{id:"b",text:"FastAPI automatically merges all sessions into one"},{id:"c",text:"This is never an issue since Depends() always shares state"},{id:"d",text:"Multiple sessions always error immediately"}], correctOptionId: "a", explanation: "If each dependency opens its own session/connection rather than sharing one scoped to the request, changes made in one won't be visible to another until committed, risking inconsistent state within a single request." },
  { id: "q-hard-fastapi-013", language: "fastapi", question: "What is the effect of using 'Depends()' on a class (rather than a function) in FastAPI?", options: [{id:"a",text:"FastAPI treats the class's __init__ parameters as dependency parameters, instantiating it per request"},{id:"b",text:"Classes cannot be used as dependencies"},{id:"c",text:"It only works for Pydantic models"},{id:"d",text:"The class's __call__ is ignored entirely"}], correctOptionId: "a", explanation: "When you use Depends(SomeClass), FastAPI resolves SomeClass's __init__ parameters as its own sub-dependencies, then instantiates it — a common pattern for grouping related dependencies." },
  { id: "q-hard-fastapi-014", language: "fastapi", question: "Why does using 'Optional[X] = None' versus 'X | None = None' matter differently across Python/Pydantic versions?", options: [{id:"a",text:"The X | None syntax requires Python 3.10+ (or 'from __future__ import annotations' for earlier via postponed evaluation) while Optional[X] works on older versions too"},{id:"b",text:"They are never interchangeable in any Python version"},{id:"c",text:"X | None only works with Pydantic v1"},{id:"d",text:"Optional[X] is deprecated and always throws an error"}], correctOptionId: "a", explanation: "PEP 604's X | None union syntax was introduced in Python 3.10; on earlier versions you either need typing.Optional[X] or a future import to use it in annotations." },
  { id: "q-hard-fastapi-015", language: "fastapi", question: "What is a risk of not setting explicit timeouts on outbound HTTP calls (e.g. via httpx) made from within a FastAPI route?", options: [{id:"a",text:"A slow/hanging downstream service can tie up a request indefinitely, potentially exhausting worker capacity under load"},{id:"b",text:"FastAPI automatically times out all outbound calls after 5 seconds"},{id:"c",text:"This has no effect on server capacity"},{id:"d",text:"httpx calls are always instant"}], correctOptionId: "a", explanation: "Without a timeout, a hung downstream dependency can hold a request (and its resources) open indefinitely, which under concurrent load can exhaust available capacity — always set explicit timeouts on outbound calls." },
  { id: "q-hard-fastapi-016", language: "fastapi", question: "Why might a Pydantic model using 'model_validate' (or the older parse_obj) on a dict silently drop unexpected extra fields unless configured otherwise?", options: [{id:"a",text:"By default, Pydantic ignores extra fields not declared on the model unless 'extra=\"forbid\"' or similar is set"},{id:"b",text:"Pydantic always raises an error on extra fields by default"},{id:"c",text:"Extra fields are always included regardless of configuration"},{id:"d",text:"This behavior can't be configured"}], correctOptionId: "a", explanation: "Pydantic's default extra-field behavior is to ignore unrecognized fields; setting model_config = {'extra': 'forbid'} makes it raise instead, which is useful for catching typos/unexpected input." },
  { id: "q-hard-fastapi-017", language: "fastapi", question: "What is a subtlety of dependency override (app.dependency_overrides) used in testing?", options: [{id:"a",text:"It replaces a dependency globally for the app instance during tests, so overrides must be cleared/reset between tests to avoid leaking into unrelated tests"},{id:"b",text:"Overrides are automatically scoped per test function with no cleanup needed"},{id:"c",text:"dependency_overrides only works with class-based dependencies"},{id:"d",text:"Overrides can't be used with Depends()"}], correctOptionId: "a", explanation: "dependency_overrides is a dict on the app instance, so overrides persist across tests unless explicitly cleared (e.g. in a fixture teardown), a common source of test pollution if forgotten." },
  { id: "q-hard-fastapi-018", language: "fastapi", question: "Why can defining a Pydantic response_model that's broader than what a route actually returns lead to confusing behavior?", options: [{id:"a",text:"FastAPI still validates/filters the actual return value against response_model, silently dropping fields not declared on it even if the route computed them"},{id:"b",text:"response_model has no effect on the actual returned data"},{id:"c",text:"Extra computed fields are always preserved regardless of response_model"},{id:"d",text:"FastAPI raises an error if any field is missing from the actual return value"}], correctOptionId: "a", explanation: "response_model acts as both documentation and an output filter — fields on the returned object that aren't declared in response_model get silently excluded from the serialized response." },
  { id: "q-hard-fastapi-019", language: "fastapi", question: "What is a subtlety of using 'async def' dependencies that internally call 'run_in_threadpool' versus a plain sync dependency function?", options: [{id:"a",text:"A plain 'def' dependency is automatically run in FastAPI's threadpool, so it already avoids blocking the loop without needing manual run_in_threadpool calls"},{id:"b",text:"Sync dependencies always block the event loop with no exceptions"},{id:"c",text:"run_in_threadpool has no purpose in FastAPI"},{id:"d",text:"Only route functions get threadpool treatment, never dependencies"}], correctOptionId: "a", explanation: "FastAPI runs regular 'def' dependency functions (like regular 'def' routes) in a threadpool automatically, so wrapping sync logic there already avoids blocking — the pattern matters for choosing sync vs async dependencies appropriately." },
  { id: "q-hard-fastapi-020", language: "fastapi", question: "Why might sharing one global httpx.AsyncClient across the app's lifetime (via lifespan) be preferred over creating a new client per request?", options: [{id:"a",text:"Reusing a client preserves connection pooling (keep-alive), avoiding the overhead of establishing a new TCP/TLS connection on every request"},{id:"b",text:"There's no performance difference between the two approaches"},{id:"c",text:"A new client per request is always faster"},{id:"d",text:"httpx clients can't be reused across requests"}], correctOptionId: "a", explanation: "Creating a new client per request discards connection pooling benefits, adding latency from repeated connection setup — a shared client (opened at startup, closed at shutdown) is more efficient for frequent outbound calls." },
  { id: "q-hard-fastapi-021", language: "fastapi", question: "What is a common pitfall when using FastAPI's automatic request body validation with a Union of Pydantic models (e.g. Union[ModelA, ModelB])?", options: [{id:"a",text:"Pydantic tries each type in order (in v1's 'smart' mode) or uses discriminators; ambiguous overlapping models can cause the wrong type to be matched"},{id:"b",text:"Union types are entirely unsupported by Pydantic"},{id:"c",text:"FastAPI always picks the first type regardless of the data"},{id:"d",text:"Union fields never validate correctly"}], correctOptionId: "a", explanation: "Without a discriminator field, Pydantic's Union resolution can be ambiguous when models overlap structurally — a discriminated union (tagging which model to use) avoids this ambiguity." },
  { id: "q-hard-fastapi-022", language: "fastapi", question: "Why is rate limiting typically implemented as external middleware/infrastructure (e.g. Redis-based) rather than purely in-process counters for a multi-worker FastAPI deployment?", options: [{id:"a",text:"In-process counters don't share state across worker processes, so limits would only apply per-worker instead of globally"},{id:"b",text:"In-process counters work perfectly fine across all workers"},{id:"c",text:"FastAPI has built-in distributed rate limiting"},{id:"d",text:"Rate limiting is never needed in production"}], correctOptionId: "a", explanation: "Since each worker process has separate memory, an in-process counter can't enforce a true global limit across all workers — a shared store like Redis is needed for accurate distributed rate limiting." },
  { id: "q-hard-fastapi-023", language: "fastapi", question: "What subtlety exists in relying on Pydantic's automatic type coercion (e.g. a string \"123\" being accepted for an int field)?", options: [{id:"a",text:"Pydantic's default 'lax' mode coerces compatible types, which can hide bugs where the client sends the wrong type but validation still passes"},{id:"b",text:"Pydantic never coerces types, always requiring exact matches"},{id:"c",text:"Type coercion always raises a warning visible to the client"},{id:"d",text:"This behavior can't be changed"}], correctOptionId: "a", explanation: "Pydantic's default lenient coercion is convenient but can mask client bugs; stricter validation modes (e.g. strict types) are available when exact type matching matters more than convenience." },
  { id: "q-hard-fl-023", language: "flutter", question: "What does 'BuildOwner' coordinate in Flutter's rendering pipeline, at a level above individual Elements?", options: [{id:"a",text:"Manages the list of dirty elements needing rebuild and orchestrates the build phase across the whole tree"},{id:"b",text:"Only manages a single widget's build"},{id:"c",text:"Handles network requests"},{id:"d",text:"Manages only animations"}], correctOptionId: "a", explanation: "BuildOwner tracks which Elements are marked dirty (needing rebuild) and drives the process of rebuilding them in the correct order during a frame." },
  { id: "q-hard-fl-024", language: "flutter", question: "Why does Flutter's layout algorithm generally flow constraints down and sizes up ('constraints go down, sizes go up')?", options: [{id:"a",text:"A parent tells its child the maximum/minimum space available (constraints); the child decides its own size within those bounds and reports it back up"},{id:"b",text:"Children decide their parent's size"},{id:"c",text:"All widgets have a fixed size regardless of constraints"},{id:"d",text:"Sizes are decided randomly at runtime"}], correctOptionId: "a", explanation: "This unidirectional flow (parent constrains child, child sizes itself and reports back) is core to Flutter's efficient single-pass layout algorithm, though there are exceptions (like relayout boundaries)." },
  { id: "q-hard-fl-025", language: "flutter", question: "What is a 'relayout boundary' and why does it matter for layout performance?", options: [{id:"a",text:"A point in the render tree where a child's size change doesn't require the parent to re-layout, limiting the scope of layout recalculation"},{id:"b",text:"A visual boundary drawn around each widget"},{id:"c",text:"A boundary that prevents any widget from resizing"},{id:"d",text:"Only relevant to network images"}], correctOptionId: "a", explanation: "When a RenderObject's size doesn't depend on its parent (e.g. it has tight constraints), it becomes a relayout boundary, so layout changes below it don't propagate upward, limiting recalculation scope." },
  { id: "q-hard-fl-026", language: "flutter", question: "Why can 'Hero' animations sometimes flicker or behave oddly when the source and destination widgets have significantly different aspect ratios or content?", options: [{id:"a",text:"Hero interpolates the widget's bounds/shape between routes, and mismatched content/aspect ratios can make the mid-transition frames look visually inconsistent"},{id:"b",text:"Hero animations always work identically regardless of the widgets involved"},{id:"c",text:"This is a bug that has no explanation"},{id:"d",text:"Hero only works with Text widgets"}], correctOptionId: "a", explanation: "Hero animates the transition between two representations of 'the same' widget across routes, and if their shapes/content differ significantly, the interpolated in-between frames can look jarring — a flightShuttleBuilder can customize this." },
  { id: "q-hard-fl-027", language: "flutter", question: "What is the significance of 'SchedulerBinding.instance.addPostFrameCallback' versus a Future.delayed(Duration.zero, ...) for post-build work?", options: [{id:"a",text:"addPostFrameCallback is tied precisely to the rendering pipeline's frame completion, while Future.delayed is scheduled via the event queue with less precise timing guarantees relative to frames"},{id:"b",text:"They are always functionally identical"},{id:"c",text:"Future.delayed always runs before the current frame renders"},{id:"d",text:"addPostFrameCallback can only be used once per app"}], correctOptionId: "a", explanation: "addPostFrameCallback hooks directly into the rendering pipeline's post-frame phase, giving more reliable timing relative to layout/paint than a generic microtask/timer-based delay." },
  { id: "q-hard-fl-028", language: "flutter", question: "Why might using 'ChangeNotifier' with many listeners on a single large object cause more rebuilds than necessary compared to splitting state into smaller, focused notifiers?", options: [{id:"a",text:"notifyListeners() on the whole object triggers ALL its listeners, even ones only interested in a part of the state that didn't change"},{id:"b",text:"ChangeNotifier automatically diffs which listeners actually need updates"},{id:"c",text:"There's no difference in rebuild behavior either way"},{id:"d",text:"ChangeNotifier can only have one listener at a time"}], correctOptionId: "a", explanation: "A single ChangeNotifier's notifyListeners() is a blunt signal — every listener rebuilds regardless of which specific field changed, which is why splitting state or using Selector-style narrowing can reduce unnecessary rebuilds." },
  { id: "q-hard-fl-029", language: "flutter", question: "What is a subtlety of using 'unawaited()' on a Future inside an async method, versus simply not awaiting it (leaving it as a bare statement)?", options: [{id:"a",text:"unawaited() is purely a lint-suppression marker signaling the omission is intentional; functionally it doesn't change execution, just silences the 'unawaited future' warning"},{id:"b",text:"unawaited() actually cancels the future"},{id:"c",text:"unawaited() makes the future run synchronously"},{id:"d",text:"unawaited() and leaving it bare behave completely differently at runtime"}], correctOptionId: "a", explanation: "unawaited() doesn't change runtime behavior — it's a no-op wrapper whose only purpose is to tell the analyzer 'yes, I meant to not await this,' avoiding the discarded-future lint warning." },
  { id: "q-hard-fl-030", language: "flutter", question: "Why does wrapping a large, mostly-static widget subtree with 'const' sometimes fail to prevent rebuilds, even though the widget's constructor is marked const-compatible?", options: [{id:"a",text:"If any single value passed into the subtree (even deep inside) is not itself a compile-time constant, the whole chain can't be const, forcing rebuilds"},{id:"b",text:"const always works regardless of what's passed in"},{id:"c",text:"const only affects the top-level widget, never children"},{id:"d",text:"This scenario is impossible"}], correctOptionId: "a", explanation: "For a widget tree to be truly const, every value flowing into it (including deeply nested ones) must be a compile-time constant — a single non-const value anywhere breaks the chain for everything depending on it." },
  { id: "q-hard-py-036", language: "python", question: "What is the difference between '==' triggering __eq__ versus Python's default identity-based equality when a class doesn't override __eq__?", options: [{id:"a",text:"Without an __eq__ override, '==' falls back to identity comparison (same as 'is'), so two 'equal-looking' instances compare unequal by default"},{id:"b",text:"Python always compares object attributes automatically without needing __eq__"},{id:"c",text:"'==' always raises an error without __eq__ defined"},{id:"d",text:"Classes automatically get value-based equality by default"}], correctOptionId: "a", explanation: "The default object.__eq__ implementation compares identity, so custom classes need to explicitly implement __eq__ (often alongside __hash__) to get meaningful value-based equality." },
  { id: "q-hard-py-037", language: "python", question: "Why does 'except (TypeError, ValueError) as e' behave differently from two separate except clauses for the same exception?", options: [{id:"a",text:"A tuple in one except clause catches any of those types with the same handling code, while separate clauses can have distinct handling logic per type"},{id:"b",text:"They are always functionally identical with no difference"},{id:"c",text:"A tuple except clause only catches the first listed type"},{id:"d",text:"This syntax is invalid in Python"}], correctOptionId: "a", explanation: "A tuple groups multiple exception types under one handler with shared logic, whereas separate except clauses let you branch to different handling code depending on which specific exception occurred." },
  { id: "q-hard-py-038", language: "python", question: "What does 'async generator' (a function with both 'async def' and 'yield') let you do that a regular generator can't?", options: [{id:"a",text:"Yield values while also being able to 'await' asynchronous operations between yields"},{id:"b",text:"Nothing different from a regular generator"},{id:"c",text:"Async generators can't use yield at all"},{id:"d",text:"They can only yield once"}], correctOptionId: "a", explanation: "An async generator combines lazy iteration (yield) with the ability to await async operations in between values, consumed via 'async for'." },
  { id: "q-hard-py-039", language: "python", question: "Why can using a generator expression instead of a list comprehension as a function argument sometimes cause subtle bugs if the generator is consumed more than once?", options: [{id:"a",text:"A generator is exhausted after one full iteration; reusing it (e.g. passing it to two functions expecting fresh iteration) yields nothing the second time"},{id:"b",text:"Generators can always be iterated an unlimited number of times"},{id:"c",text:"Generator expressions behave exactly like lists in every way"},{id:"d",text:"This scenario never causes issues"}], correctOptionId: "a", explanation: "Once a generator is fully consumed, further iteration yields nothing — unlike a list, which can be iterated repeatedly, so code assuming reusability of a generator will silently get empty results." },
  { id: "q-hard-py-040", language: "python", question: "What is a subtlety of Python's 'match' statement (structural pattern matching) with respect to class patterns and __match_args__?", options: [{id:"a",text:"Positional patterns like case Point(x, y) rely on the class defining __match_args__ to map positions to attribute names"},{id:"b",text:"match statements can't use classes as patterns at all"},{id:"c",text:"__match_args__ is unrelated to pattern matching"},{id:"d",text:"Positional class patterns work automatically for any class with no configuration"}], correctOptionId: "a", explanation: "For positional class patterns to work, the class needs __match_args__ (often auto-generated for dataclasses) specifying which attributes correspond to which positions." },
  { id: "q-hard-fastapi-024", language: "fastapi", question: "Why might using 'app.state' to store shared resources (like a DB connection pool) be preferred over module-level globals?", options: [{id:"a",text:"app.state ties the resource's lifecycle to the specific application instance, which is cleaner for testing with multiple app instances and avoids import-order issues"},{id:"b",text:"app.state and module-level globals are functionally identical with no tradeoffs"},{id:"c",text:"app.state can only store strings"},{id:"d",text:"Module-level globals are always safer"}], correctOptionId: "a", explanation: "app.state scopes shared resources to the app instance rather than the module, which avoids subtle bugs from import caching and makes it easier to spin up isolated app instances in tests." },
  { id: "q-hard-fastapi-025", language: "fastapi", question: "What is a risk of catching a broad 'Exception' in a custom FastAPI exception handler without re-raising or logging specifics?", options: [{id:"a",text:"It can silently mask bugs by converting unexpected errors into generic responses, hiding the real cause during debugging"},{id:"b",text:"FastAPI automatically logs full details regardless of your handler"},{id:"c",text:"This pattern has no downsides"},{id:"d",text:"Broad exception handlers are required by FastAPI"}], correctOptionId: "a", explanation: "A catch-all handler that just returns a generic error response without logging the original exception details makes debugging much harder, since the specific cause is lost." },
  { id: "q-hard-fastapi-026", language: "fastapi", question: "Why does the order in which middleware is added to a FastAPI app matter?", options: [{id:"a",text:"Middleware wraps in the order added, so the last-added middleware runs its 'before' logic first on the way in, and last on the way out (LIFO for the outer wrapping)"},{id:"b",text:"Middleware order never affects behavior"},{id:"c",text:"Only the first middleware added ever runs"},{id:"d",text:"Middleware always executes in a fixed order regardless of registration"}], correctOptionId: "a", explanation: "Each middleware wraps the next, so execution order forms a nested structure — later middleware ends up 'closer' to the actual request handling, which matters for things like auth-before-logging vs logging-before-auth." },
  { id: "q-hard-fastapi-027", language: "fastapi", question: "What is a subtlety of testing async FastAPI routes with pytest, regarding the need for pytest-asyncio or an async test client?", options: [{id:"a",text:"Calling an async route function directly without an event loop/test runner support won't execute it properly — you need async test infrastructure or a client that manages the loop"},{id:"b",text:"Async routes can always be tested exactly like sync functions with no special setup"},{id:"c",text:"pytest handles all async code automatically with zero configuration"},{id:"d",text:"TestClient can never be used with async routes"}], correctOptionId: "a", explanation: "Testing async code requires either an async-aware test runner (pytest-asyncio) or a client (like TestClient/httpx AsyncClient) that properly drives the event loop, or the coroutine won't actually run as expected." },
  { id: "q-hard-fastapi-028", language: "fastapi", question: "Why can validating a request against a Pydantic model with strict numeric types (e.g. StrictInt) sometimes break clients sending JSON numbers that look like ints but are floats (e.g. 5.0)?", options: [{id:"a",text:"StrictInt rejects values that aren't already exactly of type int, so a JSON float like 5.0 fails validation even though it's numerically a whole number"},{id:"b",text:"StrictInt automatically converts any numeric value silently"},{id:"c",text:"JSON has no concept of float vs int, so this can't happen"},{id:"d",text:"StrictInt behaves identically to a plain int annotation"}], correctOptionId: "a", explanation: "Strict types disable Pydantic's usual lenient coercion, so a technically-float JSON value (5.0) won't be accepted for a StrictInt field even though it represents a whole number." },
  { id: "q-hard-fastapi-029", language: "fastapi", question: "What is the significance of setting 'workers' > 1 with uvicorn/gunicorn for a FastAPI app that relies heavily on in-memory caching within request-handling code?", options: [{id:"a",text:"Each worker is a separate process with its own memory, so an in-memory cache is duplicated (and inconsistent) across workers rather than shared"},{id:"b",text:"All workers automatically share the same memory space"},{id:"c",text:"Increasing workers has no relationship to memory sharing"},{id:"d",text:"In-memory caches always sync automatically across processes"}], correctOptionId: "a", explanation: "Multi-worker deployments mean each worker process maintains its own separate memory, so relying on in-process caching leads to inconsistent state across workers unless an external shared store is used." },
  { id: "q-hard-fastapi-030", language: "fastapi", question: "Why can a Pydantic model field typed as a plain 'list' (without a generic parameter, e.g. List[str]) lead to weaker validation guarantees than expected?", options: [{id:"a",text:"An unparameterized list accepts any element type, since Pydantic has no inner type to validate items against"},{id:"b",text:"Plain 'list' behaves identically to List[str] in all cases"},{id:"c",text:"Pydantic rejects unparameterized list fields entirely"},{id:"d",text:"This has no effect on validation strictness"}], correctOptionId: "a", explanation: "Without a type parameter, Pydantic can only validate that the value is list-like, not what's inside it — List[str] additionally validates and/or coerces each element to a string." },
];
